// 解析端口号：非法输入返回 null
export function parsePort(input) {
  const s = String(input).trim();
  // 必须整体是十进制整数，Number() 的宽容截断会放过 '80abc'
  if (!/^\d+$/.test(s)) return null;
  const n = Number(s);
  if (!Number.isInteger(n)) return null;
  if (n < 1 || n > 65535) return null;
  return n;
}

