export function formatUsers(users) {
  const lines = [];
  for (const u of users) {
    if (!u.active) continue;
    lines.push(`${u.name.trim()}: ${String(u.email).trim().toLowerCase()}`);
  }
  return lines.join('\n');
}

export function formatAdmins(admins) {
  const lines = [];
  for (const a of admins) {
    if (!a.active) continue;
    lines.push(`${a.name.trim()}: ${String(a.email).trim().toLowerCase()}`);
  }
  return lines.join('\n');
}

