// 内部共享格式化：两个导出只是入参语义不同，行为完全一致
function formatEntries(list) {
  const lines = [];
  for (const e of list) {
    if (!e.active) continue;
    lines.push(`${e.name.trim()}: ${String(e.email).trim().toLowerCase()}`);
  }
  return lines.join('\n');
}

export function formatUsers(users) {
  return formatEntries(users);
}

export function formatAdmins(admins) {
  return formatEntries(admins);
}

