import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const SCRIPT = path.join(ROOT, 'scripts', 'clean.sh');

function runIn(dir, arg) {
  return execFileSync('sh', [SCRIPT, arg], { cwd: dir, encoding: 'utf8' });
}

test('拒绝删除危险目标', () => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'clean-', ));
  fs.mkdirSync(path.join(tmp, 'dist'));
  fs.writeFileSync(path.join(tmp, 'dist', 'a.txt'), 'x');
  fs.writeFileSync(path.join(tmp, 'keep.txt'), 'important');
  // 目标是仓库根时，必须拒绝执行而不是清空
  let rejected = false;
  try {
    runIn(tmp, '.');
  } catch {
    rejected = true;
  }
  assert.ok(rejected, '传入 . 时必须报错退出');
  assert.ok(fs.existsSync(path.join(tmp, 'keep.txt')), 'keep.txt 不能被删');
});
